#!/usr/bin/env python3
"""Compute deterministic numeric ground truth for CSX-278_Q2."""

from __future__ import annotations

import csv
import json
import re
from datetime import date
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_ID = "CSX-278_Q2"
EVENT_ID = "CSX-278"
TARGET_FAMILY = "enso_coupling_threshold_ledger"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
OUT = TASK_DIR / "computed_gt.json"

SOURCE_FILES = [
    "metadata/event.json",
    "metadata/files.csv",
    "data/event_reports/event_reports_001_Locked_anchor_WMO.html",
    "data/event_reports/event_reports_002_Locked_event_anchor_2020-2023_triple-dip_La_Nina_and_Horn_of_Africa_drought.json",
    "data/physical_hazard/physical_hazard_007_NOAA_PSL_ONI_data.data",
    "data/physical_hazard/physical_hazard_008_NOAA_PSL_SOI_data.data",
    "data/physical_hazard/physical_hazard_010_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/exposure_impact/exposure_impact_004_WorldPop_GP_100m_population_sum.json",
]


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []

    def handle_data(self, data: str) -> None:
        if data.strip():
            self.parts.append(data.strip())

    def text(self) -> str:
        return re.sub(r"\s+", " ", " ".join(self.parts)).strip()


def read_text(relative_path: str) -> str:
    return (PACKAGE_DIR / relative_path).read_text(encoding="utf-8", errors="ignore")


def load_json(relative_path: str) -> dict[str, Any]:
    return json.loads(read_text(relative_path))


def read_manifest_paths() -> set[str]:
    with (PACKAGE_DIR / "metadata" / "files.csv").open("r", encoding="utf-8", newline="") as handle:
        return {row["relative_path"] for row in csv.DictReader(handle)}


def html_to_text(raw_html: str) -> str:
    parser = TextExtractor()
    parser.feed(raw_html)
    return parser.text()


def parse_monthly_table(text: str) -> dict[tuple[int, int], float]:
    values: dict[tuple[int, int], float] = {}
    for line in text.splitlines():
        parts = line.split()
        if len(parts) != 13 or not parts[0].isdigit():
            continue
        year = int(parts[0])
        for month, raw in enumerate(parts[1:], start=1):
            value = float(raw)
            if value > -90:
                values[(year, month)] = value
    return values


def parse_iso_date(raw: str) -> date:
    year, month, day = (int(part) for part in raw.split("-"))
    return date(year, month, day)


def month_sequence(start_day: date, end_day: date) -> list[tuple[int, int]]:
    year, month = start_day.year, start_day.month
    months: list[tuple[int, int]] = []
    while (year, month) <= (end_day.year, end_day.month):
        months.append((year, month))
        month += 1
        if month == 13:
            month = 1
            year += 1
    return months


def extract_food_insecure_millions(report_text: str) -> float:
    match = re.search(r"more than\s+([0-9]+(?:\.[0-9]+)?)\s+million people are highly food insecure", report_text, re.I)
    if not match:
        raise ValueError("Food-insecurity count not found in report text")
    return float(match.group(1))


def require_manifest_sources() -> None:
    manifest_paths = read_manifest_paths()
    missing = sorted(path for path in SOURCE_FILES if path.startswith("data/") and path not in manifest_paths)
    if missing:
        raise ValueError(f"Missing package files: {missing}")


def build_result() -> dict[str, Any]:
    require_manifest_sources()

    event = load_json("metadata/event.json")
    anchor = load_json(
        "data/event_reports/event_reports_002_Locked_event_anchor_2020-2023_triple-dip_La_Nina_and_Horn_of_Africa_drought.json"
    )
    report_text = html_to_text(read_text("data/event_reports/event_reports_001_Locked_anchor_WMO.html"))
    oni = parse_monthly_table(read_text("data/physical_hazard/physical_hazard_007_NOAA_PSL_ONI_data.data"))
    soi = parse_monthly_table(read_text("data/physical_hazard/physical_hazard_008_NOAA_PSL_SOI_data.data"))
    precip = load_json("data/physical_hazard/physical_hazard_010_GPM_IMERG_V07_event_accumulated_precipitation.json")
    population = load_json("data/exposure_impact/exposure_impact_004_WorldPop_GP_100m_population_sum.json")

    event_start = parse_iso_date(anchor["temporal_window"]["start_date"])
    event_end = parse_iso_date(anchor["temporal_window"]["end_date"])
    precip_start = parse_iso_date(precip["start"])
    precip_end = parse_iso_date(precip["end"])
    months = month_sequence(event_start, event_end)

    missing_months = [month for month in months if month not in oni or month not in soi]
    if missing_months:
        raise ValueError(f"Missing index months: {missing_months}")

    cold_oni_months = sum(oni[month] <= -0.5 for month in months)
    positive_soi_months = sum(soi[month] > 0 for month in months)
    coupled_months = sum(oni[month] <= -0.5 and soi[month] > 0 for month in months)
    strong_coupled_months = sum(oni[month] <= -0.8 and soi[month] >= 0.7 for month in months)
    event_days = (event_end - event_start).days + 1
    short_slice_days = (precip_end - precip_start).days + 1
    food_insecure_millions = extract_food_insecure_millions(report_text)
    compact_population = float(population["population_sum"]["population"])

    score = round(coupled_months / len(months), 3)
    short_slice_fraction = round(short_slice_days / event_days, 3)
    people_ratio_min = round((food_insecure_millions * 1_000_000) / compact_population, 3)
    classification = "sustained_coupled_event" if score >= 0.75 else "mixed_event"

    primary_gt = {
        "answer": {
            "event_months": len(months),
            "cold_oni_months": cold_oni_months,
            "positive_soi_months": positive_soi_months,
            "coupled_months": coupled_months,
            "strong_coupled_months": strong_coupled_months,
            "coupled_persistence_score": score,
            "short_slice_fraction": short_slice_fraction,
            "people_ratio_min": people_ratio_min,
        },
        "classification": classification,
        "calculation_note": (
            "The ledger uses 25/31 for coupled persistence, 46/942 for the short "
            "precipitation slice, and 20000000/4982987.813 for the people-scale ratio."
        ),
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "numeric_tolerances": {
            "coupled_persistence_score": {"target": score, "absolute_tolerance": 0.001},
            "event_months": {"target": len(months), "absolute_tolerance": 0},
            "cold_oni_months": {"target": cold_oni_months, "absolute_tolerance": 0},
            "positive_soi_months": {"target": positive_soi_months, "absolute_tolerance": 0},
            "coupled_months": {"target": coupled_months, "absolute_tolerance": 0},
            "strong_coupled_months": {"target": strong_coupled_months, "absolute_tolerance": 0},
            "short_slice_fraction": {"target": short_slice_fraction, "absolute_tolerance": 0.001},
            "people_ratio_min": {"target": people_ratio_min, "absolute_tolerance": 0.01},
        },
        "key_values": {
            "classification": classification,
            "event_days": event_days,
            "short_slice_days": short_slice_days,
            "food_insecure_millions_floor": food_insecure_millions,
            "compact_aoi_population": round(compact_population, 3),
            "oni_threshold": -0.5,
            "strong_oni_threshold": -0.8,
            "strong_soi_threshold": 0.7,
            "event_name": event["event_name"],
            "event_window": f"{event_start.isoformat()} to {event_end.isoformat()}",
            "location": anchor["spatial_window"]["location_text"],
        },
        "formulas": {
            "coupled_persistence_score": "coupled_months / event_months",
            "short_slice_fraction": "inclusive_short_precipitation_days / inclusive_event_days",
            "people_ratio_min": "20000000 / compact_aoi_population",
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Ledger structure",
                    "points": 3,
                    "description": "Returns compact JSON with the requested numeric fields, classification, and formula note.",
                },
                {
                    "name": "Monthly threshold counts",
                    "points": 5,
                    "description": "Reports 31 event months, 25 cold ONI months, 31 positive SOI months, and 25 coupled months.",
                },
                {
                    "name": "Strong coupling and score",
                    "points": 4,
                    "description": "Reports 14 strong coupled months and computes the persistence score as 25/31 = 0.806.",
                },
                {
                    "name": "Short-slice fraction",
                    "points": 3,
                    "description": "Uses inclusive dates to compute 46/942 = 0.049 for the precipitation-slice fraction.",
                },
                {
                    "name": "People-scale ratio",
                    "points": 3,
                    "description": "Computes the minimum regional-to-compact-population ratio as 20000000/4982987.813 = 4.014.",
                },
                {
                    "name": "Rounding and units",
                    "points": 2,
                    "description": "Keeps month counts as integers and rounds derived fractions or ratios to three decimals with clear units.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }


def main() -> None:
    result = build_result()
    OUT.write_text(json.dumps(result, ensure_ascii=True, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
